// Photorealistic mockups for the prototype, generated by Gemini from each demo brand's real logo.
// The key is read from prototypes/studio/.env.local (git-ignored) and never printed. Output goes to
// src/data/mockups/<slug>/<scene>.webp (git-ignored: the pictures carry trademarks). Already generated
// files are kept, so the script can be re-run after a failure. `node scripts/gen-mockups.mjs [slug…]`.
import { existsSync } from 'node:fs';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { loadEnvFile } from 'node:process';

const here = new URL('../', import.meta.url);
const envFile = new URL('.env.local', here);
if (existsSync(envFile)) loadEnvFile(envFile);
const KEY = process.env.GEMINI_API_KEY ?? '';
if (!/^[\w.-]{20,}$/.test(KEY)) {
  console.error('GEMINI_API_KEY missing or malformed in prototypes/studio/.env.local');
  process.exit(1);
}
const API = 'https://generativelanguage.googleapis.com/v1beta';
const headers = { 'content-type': 'application/json', 'x-goog-api-key': KEY };

const repo = new URL('../../', here);
const raster = await import(new URL('packages/svg-engine/dist/raster/index.js', repo).href);
// sharp as installed for svg-engine (resolved from that package, pnpm layout).
const sharp = createRequire(new URL('packages/svg-engine/package.json', repo))('sharp');
const rasterizer = raster.createNodeRasterizer();

// Scenes: one photograph each, the logo placed as a real print, embroidery, sign or screen would show it.
export const SCENES = [
  {
    key: 'cards',
    label: 'Cartes de visite',
    prompt:
      'two premium business cards on a warm oak desk, one face up showing the logo centred on a {primary} card, one face down in {light}, soft window light from the left, shallow depth of field, a ceramic coffee cup out of focus',
  },
  {
    key: 'store',
    label: 'Devanture',
    prompt:
      'a street-level shop facade at golden hour, the logo as a large illuminated sign above the entrance, the facade painted {primary} with {accent} details, people blurred walking by, 35mm street photography',
  },
  {
    key: 'tote',
    label: 'Tote bag',
    prompt:
      'a natural canvas tote bag carried on the shoulder of a person in a sunlit city street, the logo screen-printed on the bag, cropped at the torso, no face visible, editorial fashion photography',
  },
  {
    key: 'tee',
    label: 'T-shirt',
    prompt:
      'a {primary} cotton t-shirt neatly folded on a light concrete surface with the logo printed on the chest, studio product photography, soft shadows, visible fabric texture',
  },
  {
    key: 'phone',
    label: 'Application',
    prompt:
      'a hand holding a modern smartphone in a bright café, the screen shows a clean mobile app home screen using the brand colours {primary} and {accent} with the logo in the header, screen sharp and readable, background softly blurred',
  },
  {
    key: 'billboard',
    label: 'Affichage',
    prompt:
      'a large urban billboard on a modern building facade at dusk, the poster in {primary} with the logo large and centred and lots of empty space, warm city lights, pedestrians blurred in the foreground',
  },
  {
    key: 'office',
    label: 'Signalétique',
    prompt:
      'a modern office reception wall in {light} with the logo mounted as brushed metal 3D letters with subtle backlight, architectural interior photography, wide angle, clean and minimal',
  },
];

const RULES = [
  'Ultra-realistic commercial photograph for a premium brand-identity case study, as published by a top design agency.',
  'Shot on a medium-format camera, 85 mm lens, natural soft light, physically accurate shadows and reflections, true-to-life materials (paper fibres, fabric weave, brushed metal, glass), subtle film grain, no CGI look.',
  'The attached image is the brand logo: reproduce it EXACTLY as given — same shapes, same colours, same proportions, crisp edges — applied realistically to the surface (print, embroidery, sign, screen) following the perspective and lighting. Never redraw it, never add or alter letters, never invent another logo or any other text.',
  'Calm, minimal, elegant composition with generous negative space, colour grading harmonious with the brand palette. No watermark, no frame, no caption. Vertical 4:5 framing.',
].join(' ');

async function pickModel() {
  const response = await fetch(`${API}/models?pageSize=200`, { headers });
  if (!response.ok) throw new Error(`models: HTTP ${String(response.status)}`);
  const { models = [] } = await response.json();
  const names = models
    .filter((m) => (m.supportedGenerationMethods ?? []).includes('generateContent'))
    .map((m) => m.name.replace(/^models\//, ''))
    .filter((name) => name.includes('image'));
  // Best quality first; the flash model as the always-available fallback.
  const preference = [
    /^gemini-3-pro-image$/,
    /gemini-3.*pro.*image/,
    /^gemini-3\.1-flash-image$/,
    /gemini-2\.5-flash-image/,
    /image/,
  ];
  for (const pattern of preference) {
    const found = names.find((name) => pattern.test(name));
    if (found) return found;
  }
  throw new Error(`no image model available (${names.join(', ') || 'none'})`);
}

async function generate(model, prompt, logoPng) {
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const response = await fetch(`${API}/models/${model}:generateContent`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        contents: [
          {
            role: 'user',
            parts: [
              { text: prompt },
              {
                inline_data: {
                  mime_type: 'image/png',
                  data: Buffer.from(logoPng).toString('base64'),
                },
              },
            ],
          },
        ],
        generationConfig: { responseModalities: ['IMAGE'], imageConfig: { aspectRatio: '4:5' } },
      }),
    });
    if (response.ok) {
      const body = await response.json();
      const part = body.candidates?.[0]?.content?.parts?.find((p) => p.inlineData ?? p.inline_data);
      const data = part?.inlineData?.data ?? part?.inline_data?.data;
      if (data) return Buffer.from(data, 'base64');
      console.warn(
        `  no image in answer (attempt ${String(attempt)}): ${body.candidates?.[0]?.finishReason ?? 'unknown'}`,
      );
    } else {
      const text = (await response.text()).slice(0, 200).replace(KEY, '***');
      console.warn(`  HTTP ${String(response.status)} (attempt ${String(attempt)}): ${text}`);
      if (response.status === 400 || response.status === 403) break;
    }
    await new Promise((resolve) => setTimeout(resolve, 4000 * attempt));
  }
  return null;
}

const brands = JSON.parse(await readFile(new URL('src/data/brands.json', here), 'utf8'));
const only = process.argv.slice(2);
const model = process.env.GEN_MODEL ?? (await pickModel());
console.log(`model: ${model}`);
let made = 0;
for (const brand of brands.filter((b) => only.length === 0 || only.includes(b.slug))) {
  const dir = new URL(`src/data/mockups/${brand.slug}/`, here);
  await mkdir(dir, { recursive: true });
  const logo = await rasterizer.rasterize(brand.logo, 1024);
  if (!logo.ok) {
    console.warn(`${brand.slug}: logo not rasterized, skipped`);
    continue;
  }
  const colours = {
    primary: brand.roles.primary.hex,
    accent: brand.roles.accent.hex,
    light: brand.roles.neutralLight.hex,
  };
  // GEN_SCENES=cards,store limits a run to some scenes (tests, retries).
  const wanted = (process.env.GEN_SCENES ?? '').split(',').filter(Boolean);
  for (const scene of SCENES.filter((s) => wanted.length === 0 || wanted.includes(s.key))) {
    const target = new URL(`${scene.key}.webp`, dir);
    if (existsSync(target)) continue;
    const prompt = `${scene.prompt.replace(/\{(\w+)\}/g, (_, name) => colours[name] ?? name)}. ${RULES}`;
    console.log(`${brand.slug} / ${scene.key}…`);
    const image = await generate(model, prompt, logo.value.png);
    if (!image) continue;
    await writeFile(
      target,
      await sharp(image)
        .resize({ width: 1200, withoutEnlargement: true })
        .webp({ quality: 82 })
        .toBuffer(),
    );
    made += 1;
  }
}
console.log(`${String(made)} new mockups`);
